"use client";

import { motion, useReducedMotion, type Transition } from "motion/react";
import { type ComponentPropsWithoutRef, type KeyboardEvent, useRef, useState } from "react";

import { cn } from "@/lib/utils";

/** Props for pagination dots. Pass `value` to control the active slide, or `defaultValue` to let the dots hold it. */
export type PaginationDotsProps = Omit<ComponentPropsWithoutRef<"div">, "children" | "defaultValue" | "onChange"> & {
  /** How many slides there are. */
  count: number;
  /** The active slide, counted from 0. */
  value?: number;
  defaultValue?: number;
  onValueChange?: (index: number) => void;
  /** Names one dot. The default reads "Slide 2 of 5". */
  getLabel?: (index: number, count: number) => string;
};

// Critically damped: one dot gives up its width while the next takes it, and neither wobbles.
const SPRING: Transition = { type: "spring", stiffness: 500, damping: 45, mass: 1 };
const INSTANT: Transition = { duration: 0 };
const DOT = 8;
const BAR = 24;

const slideLabel = (index: number, count: number) => `Slide ${index + 1} of ${count}`;

/**
 * Dots under a set of slides. The active dot stretches into a short bar, and
 * moving on hands that stretch to the next dot.
 */
export function PaginationDots({
  count,
  value,
  defaultValue = 0,
  onValueChange,
  getLabel = slideLabel,
  className,
  onKeyDown,
  "aria-label": ariaLabel = "Slides",
  ...rootProps
}: PaginationDotsProps) {
  const [ownValue, setOwnValue] = useState(defaultValue);
  const last = Math.max(count - 1, 0);
  const active = Math.min(Math.max(value ?? ownValue, 0), last);
  const reduceMotion = useReducedMotion();
  const dots = useRef<(HTMLButtonElement | null)[]>([]);

  const select = (index: number) => {
    if (index === active) return;
    if (value === undefined) setOwnValue(index);
    onValueChange?.(index);
  };

  const handleKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    onKeyDown?.(event);
    if (event.defaultPrevented) return;
    let next: number;
    if (event.key === "ArrowRight" || event.key === "ArrowDown") next = Math.min(active + 1, last);
    else if (event.key === "ArrowLeft" || event.key === "ArrowUp") next = Math.max(active - 1, 0);
    else if (event.key === "Home") next = 0;
    else if (event.key === "End") next = last;
    else return;

    event.preventDefault();
    dots.current[next]?.focus();
    select(next);
  };

  return (
    <div
      role="group"
      aria-label={ariaLabel}
      {...rootProps}
      onKeyDown={handleKeyDown}
      className={cn("inline-flex items-center", className)}
    >
      {Array.from({ length: count }, (_, index) => {
        const current = index === active;
        return (
          <button
            key={index}
            ref={(node) => {
              dots.current[index] = node;
            }}
            type="button"
            aria-label={getLabel(index, count)}
            aria-current={current ? "true" : undefined}
            // One tab stop for the set; the arrow keys move inside it.
            tabIndex={current ? 0 : -1}
            onClick={() => select(index)}
            // The button is 44px square around an 8px dot on a phone, and 24px wide from `sm` up.
            className="group flex h-11 cursor-pointer touch-manipulation items-center px-4.5 outline-none sm:px-2"
          >
            <motion.span
              aria-hidden="true"
              initial={false}
              // Width is a layout property, but these are a few 8px boxes and the row keeps its total width.
              animate={{ width: current ? BAR : DOT }}
              transition={reduceMotion ? INSTANT : SPRING}
              className={cn(
                "block h-2 rounded-full motion-safe:transition-colors motion-safe:duration-200",
                "group-focus-visible:ring-2 group-focus-visible:ring-ring group-focus-visible:ring-offset-2 group-focus-visible:ring-offset-background",
                current ? "bg-primary" : "bg-muted-foreground/40 group-hover:bg-muted-foreground/70",
              )}
            />
          </button>
        );
      })}
    </div>
  );
}
